pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // the test contract is the owner of c (deployed from here) and must accept ETH refunds
    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e30);

        // 1. arbitrary actor deposits via the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk, "fallback deposit should succeed");
        assertTrue(c.depositsCount() == 1, "one deposit counted");

        // 2. owner (this contract, the deployer) performs the guarded withdrawAll
        vm.deal(address(c), address(c).balance);
        try c.withdrawAll() {
            // RULE: the onlyOwner guard must not change any state;
            // depositsCount still equals the number of fallback deposits (1).
            assertTrue(c.depositsCount() == 1, "guarded call must not bump depositsCount");
        } catch {
            // even if the withdrawal reverts, the guard itself must not bump the counter
            assertTrue(c.depositsCount() == 1, "guarded call must not bump depositsCount");
        }
    }
}

